function DynamicCategoryManager({ categories, setCategories, products, notify }: { categories: Category[]; setCategories: (items: Category[]) => void; products: Product[]; notify: (message: string) => void }) {
  void LegacyAdminCategories
  const [search, setSearch] = useState('')
  const [status, setStatus] = useState('All')
  const [editing, setEditing] = useState<Category | null>(null)
  const [attributeName, setAttributeName] = useState('')
  const [attributeType, setAttributeType] = useState<AttributeType>('Dropdown')
  const [attributeValue, setAttributeValue] = useState('')
  const apiToken = sessionStorage.getItem('murugesan-auth-token') || ''
  const visible = categories.filter((category) => category.name.toLowerCase().includes(search.toLowerCase()) && (status === 'All' || (category.active !== false ? 'Active' : 'Inactive') === status))
  const update = async (category: Category) => { const response = await fetch(`/api/categories/${category.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiToken}` }, body: JSON.stringify({ name: category.name, slug: category.slug, parentId: category.parentId || null, imageUrl: category.image || null, description: category.description, status: category.active === false ? 'INACTIVE' : 'ACTIVE', sortOrder: category.order || 0 }) }); if (!response.ok) return notify('Unable to update category'); const saved = await response.json() as Category; setCategories(categories.map((item) => item.id === saved.id ? saved : item)); notify('Category updated') }
  const upload = async (file?: File) => { if (!file || !editing) return; const form = new FormData(); form.append('image', file); const response = await fetch('/api/images', { method: 'POST', headers: { Authorization: `Bearer ${apiToken}` }, body: form }); if (!response.ok) return notify('Unable to upload category image'); const result = await response.json() as { url: string }; setEditing({ ...editing, image: result.url }); notify('Category image uploaded') }
  const addAttribute = () => { if (!editing || !attributeName.trim()) return; const values = ['Dropdown', 'Multi-select', 'Radio Button'].includes(attributeType) ? attributeValue.split(',').map((value) => value.trim()).filter(Boolean) : []; setEditing({ ...editing, attributes: [...(editing.attributes || []), { id: Date.now(), name: attributeName.trim(), type: attributeType, values }] }); setAttributeName(''); setAttributeValue('') }
  const save = async (event: React.FormEvent) => { event.preventDefault(); if (!editing?.name.trim()) return; const payload = { name: editing.name.trim(), slug: editing.slug?.trim(), parentId: editing.parentId || null, imageUrl: editing.image || null, description: editing.description || '', status: editing.active === false ? 'INACTIVE' : 'ACTIVE', sortOrder: editing.order || categories.length + 1 }; const response = await fetch(editing.id ? `/api/categories/${editing.id}` : '/api/categories', { method: editing.id ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiToken}` }, body: JSON.stringify(payload) }); if (!response.ok) return notify('Unable to save category'); const category = await response.json() as Category; setCategories(categories.some((item) => item.id === category.id) ? categories.map((item) => item.id === category.id ? category : item) : [...categories, category]); setEditing(null); notify('Category saved') }
  const remove = async (category: Category) => { const count = products.filter((product) => product.categoryId === category.id || product.category === category.name).length; if (!window.confirm(`${count ? `Archive ${category.name}?\n\nThis category contains ${count} product${count === 1 ? '' : 's'}.` : `Delete ${category.name}?`}\n\nThis action cannot be undone.`)) return; const response = await fetch(`/api/categories/${category.id}/archive`, { method: 'PATCH', headers: { Authorization: `Bearer ${apiToken}` } }); if (!response.ok) return notify('Unable to archive category'); setCategories(categories.filter((item) => item.id !== category.id)); notify(count ? 'Category archived' : 'Category deleted') }
  return <><div className="admin-topline"><div><p className="eyebrow">CATALOGUE / ORGANISE</p><h1>Categories <span className="count-badge">{categories.length}</span></h1><p>Manage hierarchy, images, status and category-specific attributes.</p></div><button className="button blue" onClick={() => setEditing({ id: Date.now(), name: '', description: '', parentId: null, active: true, slug: '', order: categories.length + 1 })}>+ Add Category</button></div><div className="table-toolbar"><label className="search"><span>⌕</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search categories" /></label><select value={status} onChange={(event) => setStatus(event.target.value)}><option>All</option><option>Active</option><option>Inactive</option></select></div><div className="category-admin-grid">{visible.map((category) => <div className="category-admin-card" key={category.id}>{category.image ? <img src={category.image} alt="" /> : <span>◇</span>}<strong>{category.name}</strong><small>{category.parentId ? `Under ${categories.find((item) => item.id === category.parentId)?.name || 'category'}` : 'Top-level'} · {products.filter((product) => product.category === category.name).length} products</small><small>{category.active === false ? 'Inactive' : 'Active'} · {category.attributes?.length || 0} attributes</small><div><button onClick={() => setEditing(category)}>Edit</button><button onClick={() => update({ ...category, active: category.active === false })}>{category.active === false ? 'Enable' : 'Disable'}</button><button onClick={() => remove(category)}>Delete</button></div></div>)}</div>{editing && <div className="form-overlay"><form className="product-form category-form" onSubmit={save}><div className="form-heading"><div><p className="eyebrow">CATEGORY MANAGEMENT</p><h2>{editing.name ? 'Edit Category' : 'Add Category'}</h2></div><button type="button" onClick={() => setEditing(null)}>×</button></div><label className="dropzone">{editing.image && <img src={editing.image} alt="Category preview" />}<strong>{editing.image ? 'Replace Category Image' : 'Upload Category Image'}</strong><input type="file" accept="image/*" onChange={(event) => upload(event.target.files?.[0])} /></label><div className="form-grid"><label>Category Name *<input required value={editing.name} onChange={(event) => setEditing({ ...editing, name: event.target.value })} /></label><label>Parent Category<select value={editing.parentId || ''} onChange={(event) => setEditing({ ...editing, parentId: event.target.value ? Number(event.target.value) : null })}><option value="">None</option>{categories.filter((category) => category.id !== editing.id).map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label>URL Slug<input value={editing.slug || ''} onChange={(event) => setEditing({ ...editing, slug: event.target.value })} /></label><label>Status<select value={editing.active === false ? 'Inactive' : 'Active'} onChange={(event) => setEditing({ ...editing, active: event.target.value === 'Active' })}><option>Active</option><option>Inactive</option></select></label><label>Description<textarea value={editing.description} onChange={(event) => setEditing({ ...editing, description: event.target.value })} /></label></div><div className="attribute-builder"><div className="panel-heading"><h2>Manage Attributes</h2><small>Configure fields shown for products in this category.</small></div>{(editing.attributes || []).map((attribute) => <div className="attribute-row" key={attribute.id}><strong>{attribute.name}</strong><span>{attribute.type}{attribute.values.length ? ` · ${attribute.values.join(', ')}` : ''}</span><button type="button" onClick={() => setEditing({ ...editing, attributes: editing.attributes?.filter((item) => item.id !== attribute.id) })}>Delete</button></div>)}<div className="attribute-add"><input value={attributeName} onChange={(event) => setAttributeName(event.target.value)} placeholder="Attribute name" /><select value={attributeType} onChange={(event) => setAttributeType(event.target.value as AttributeType)}>{['Dropdown', 'Multi-select', 'Text', 'Number', 'Number Range', 'Boolean / Yes-No', 'Color', 'Image', 'Radio Button'].map((type) => <option key={type}>{type}</option>)}</select><input value={attributeValue} onChange={(event) => setAttributeValue(event.target.value)} placeholder="Values, comma separated" disabled={!['Dropdown', 'Multi-select', 'Radio Button'].includes(attributeType)} /><button type="button" onClick={addAttribute}>+ Add Attribute</button></div></div><div className="form-actions"><button type="button" className="text-button" onClick={() => setEditing(null)}>Cancel</button><button className="button blue" type="submit">Save Category</button></div></form></div>}</>
}
function AdminExtras({ products, onAdd }: { products: Product[]; onAdd: () => void }) { const lowStock = products.filter((product) => product.stock > 0 && product.stock < 10); return <><div className="admin-dashboard-grid"><section className="admin-panel sales-panel"><div className="panel-heading"><div><p className="eyebrow">SALES OVERVIEW</p><h2>Store activity</h2></div><select><option>This month</option></select></div><svg viewBox="0 0 600 180" role="img" aria-label="Sales overview chart"><path d="M0 142 C55 112 74 134 122 98 S187 117 235 79 S303 111 345 69 S418 96 457 45 S520 76 600 24" fill="none" stroke="#874777" strokeWidth="4" /><path d="M0 142 C55 112 74 134 122 98 S187 117 235 79 S303 111 345 69 S418 96 457 45 S520 76 600 24 V180 H0Z" fill="#874777" opacity=".1" /></svg><div className="chart-legend"><span>Total sales <b>₹4,82,750</b></span><span>Average order <b>₹1,547</b></span><span>Customers <b>268</b></span></div></section><section className="admin-panel date-panel"><p className="eyebrow">TODAY'S DATE</p><strong>03 Sep 2026</strong><span>Thursday</span><b>▣</b></section><section className="admin-panel enquiry-panel"><div className="panel-heading"><h2>Recent enquiries</h2><button className="text-button">View all ↗</button></div>{['Siva Electricals', 'R.K. Enterprises', 'Kumar Traders', 'Maha Electricals'].map((name, index) => <div className="enquiry-row" key={name}><span>#{1052 - index}</span><strong>{name}</strong><i className={index === 1 ? 'processing' : index === 2 ? 'pending' : ''}>{index === 1 ? 'Processing' : index === 2 ? 'Pending' : 'New'}</i><b>{money([2850, 1450, 3220, 4780][index])}</b></div>)}</section><section className="admin-panel stock-panel"><div className="panel-heading"><h2>Low stock alerts</h2><button className="text-button">View all ↗</button></div>{(lowStock.length ? lowStock : products.slice(0, 4)).map((product) => <div className="stock-row" key={product.id}><span>{product.name}</span><small>{product.code}</small><b>{product.stock}</b></div>)}</section></div><div className="quick-actions"><button onClick={onAdd}>＋ Add Product</button><button>▦ Manage Categories</button><button>▣ View Orders</button><button>▣ Inventory Report</button><button>◇ Add Offer</button></div></> }
