type Category = { id: number; name: string; description: string; parentId?: number | null; image?: string; active?: boolean; slug?: string; createdAt?: string; order?: number; brands?: string[]; types?: string[]; attributes?: CategoryAttribute[] }
type Screen = 'home' | 'products' | 'detail' | 'cart' | 'login' | 'customer-login' | 'account' | 'admin'
