const categoriesSeed: Category[] = ['Electrical Switches', 'Sockets', 'Wires & Cables', 'Lighting', 'Fan Regulators', 'Electrical Accessories', 'Tools', 'Hardware', 'Plumbing Accessories', 'Other Products'].map((name, id) => ({ id: id + 1, name, description: 'Reliable products for everyday work.' }))
